1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21	)
22	
23	// Version is the baseline release identifier.
24	const Version = "0.1.0"
25	
26	const metricsPath = "/api/v1/metrics"
27	
28	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
29	
30	type health struct {
31		Status  string `json:"status"`
32		Service string `json:"service"`
33		Version string `json:"version"`
34	}
35	
36	// series is one uniquely identified time series: name + full label set.
37	type series struct {
38		name   string
39		typ    string
40		labels map[string]string
41	
42		// counter/gauge state
43		value float64
44	
45		// histogram state
46		bucketBounds []float64 // strictly increasing, fixed at first write
47		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
48		count        int64
49		sum          float64
50	}
51	
52	type metricStore struct {
53		mu     sync.RWMutex
54		series map[string]*series
55	
56		// alert rules keyed by rule id; guarded by mu so rule replacement and
57		// alert evaluation are atomic with metric commits.
58		rules map[string]*alertRule
59	
60		// silences keyed by silence id; same lock so alert evaluation reads
61		// metrics, rules and silences from one consistent snapshot.
62		silences map[string]*silence
63	
64		// inhibit rules keyed by rule id; same lock so alert evaluation also
65		// reads inhibit rules from the same consistent snapshot.
66		inhibitions map[string]*inhibitRule
67	
68		// notification routes keyed by route id; same lock so the notification
69		// plan reads routes from the same snapshot as alert evaluation.
70		notificationRoutes map[string]*notificationRoute
71	
72		// SLO definitions keyed by SLO id; same lock so status evaluation reads
73		// definitions and counters from one consistent snapshot.
74		slos map[string]*sloDefinition
75	}
76	
77	func newMetricStore() *metricStore {
78		return &metricStore{
79			series:             make(map[string]*series),
80			rules:              make(map[string]*alertRule),
81			silences:           make(map[string]*silence),
82			inhibitions:        make(map[string]*inhibitRule),
83			notificationRoutes: make(map[string]*notificationRoute),
84			slos:               make(map[string]*sloDefinition),
85		}
86	}
87	
88	// validatedSample is a sample that passed all format and value checks.
89	type validatedSample struct {
90		key     string
91		name    string
92		typ     string
93		labels  map[string]string
94		value   float64
95		buckets []float64 // non-nil for histograms
96	}
97	
98	// checkAndApply validates the batch against the current state (and against
99	// itself) and then commits it in array order. A false result signals a type or
100	// bucket-boundary conflict; in that case no state is mutated.
101	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
102		s.mu.Lock()
103		defer s.mu.Unlock()
104	
105		// First pass: conflict detection against committed state and earlier
106		// samples in the same batch.
107		resolved := make(map[string]*series, len(batch))
108		for _, sm := range batch {
109			existing, ok := s.series[sm.key]
110			if !ok {
111				if shadow, seen := resolved[sm.key]; seen {
112					existing, ok = shadow, true
113				}
114			}
115			if ok {
116				if existing.typ != sm.typ {
117					return false
118				}
119				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
120					return false
121				}
122				resolved[sm.key] = existing
123				continue
124			}
125			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
126		}
127	
128		// Second pass: commit in order.
129		for _, sm := range batch {
130			cur, ok := s.series[sm.key]
131			if !ok {
132				cur = &series{
133					name:         sm.name,
134					typ:          sm.typ,
135					labels:       sm.labels,
136					bucketBounds: append([]float64(nil), sm.buckets...),
137				}
138				if sm.typ == "histogram" {
139					cur.bucketCounts = make([]int64, len(sm.buckets))
140				}
141				s.series[sm.key] = cur
142			}
143			switch sm.typ {
144			case "counter":
145				cur.value += sm.value
146			case "gauge":
147				cur.value = sm.value
148			case "histogram":
149				cur.count++
150				cur.sum += sm.value
151				for i, bound := range cur.bucketBounds {
152					if sm.value <= bound {
153						cur.bucketCounts[i]++
154					}
155				}
156			}
157		}
158		return true
159	}
160	
161	type seriesOutput struct {
162		Name    string            `json:"name"`
163		Type    string            `json:"type"`
164		Labels  map[string]string `json:"labels"`
165		Value   *float64          `json:"value,omitempty"`
166		Count   *int64            `json:"count,omitempty"`
167		Sum     *float64          `json:"sum,omitempty"`
168		Buckets []bucketOutput    `json:"buckets,omitempty"`
169	}
170	
171	type bucketOutput struct {
172		LE    float64 `json:"le"`
173		Count int64   `json:"count"`
174	}
175	
176	// query returns matching series as ready-to-encode outputs. A series matches
177	// when its name equals name exactly and it contains every selector label.
178	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
179		s.mu.RLock()
180		defer s.mu.RUnlock()
181	
182		out := make([]seriesOutput, 0)
183		for _, cur := range s.series {
184			if cur.name != name {
185				continue
186			}
187			matched := true
188			for k, v := range selector {
189				got, ok := cur.labels[k]
190				if !ok || got != v {
191					matched = false
192					break
193				}
194			}
195			if !matched {
196				continue
197			}
198			item := seriesOutput{
199				Name:   cur.name,
200				Type:   cur.typ,
201				Labels: copyLabels(cur.labels),
202			}
203			switch cur.typ {
204			case "counter", "gauge":
205				v := cur.value
206				item.Value = &v
207			case "histogram":
208				c, sum := cur.count, cur.sum
209				item.Count = &c
210				item.Sum = &sum
211				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
212				for i, bound := range cur.bucketBounds {
213					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
214				}
215			}
216			out = append(out, item)
217		}
218	
219		sort.Slice(out, func(i, j int) bool {
220			return compareLabels(out[i].Labels, out[j].Labels) < 0
221		})
222		return out
223	}
224	
225	// compareLabels imposes a normalized lexicographic order on full label sets:
226	// keys are sorted, then (key, value) pairs are compared element-wise, and a
227	// shorter pair list sorts first when it is a prefix of a longer one.
228	func compareLabels(a, b map[string]string) int {
229		ka := sortedKeys(a)
230		kb := sortedKeys(b)
231		n := len(ka)
232		if len(kb) < n {
233			n = len(kb)
234		}
235		for i := 0; i < n; i++ {
236			if ka[i] != kb[i] {
237				return strings.Compare(ka[i], kb[i])
238			}
239			if a[ka[i]] != b[kb[i]] {
240				return strings.Compare(a[ka[i]], b[kb[i]])
241			}
242		}
243		switch {
244		case len(ka) < len(kb):
245			return -1
246		case len(ka) > len(kb):
247			return 1
248		default:
249			return 0
250		}
251	}
252	
253	func sortedKeys(m map[string]string) []string {
254		keys := make([]string, 0, len(m))
255		for k := range m {
256			keys = append(keys, k)
257		}
258		sort.Strings(keys)
259		return keys
260	}
261	
262	func copyLabels(in map[string]string) map[string]string {
263		out := make(map[string]string, len(in))
264		for k, v := range in {
265			out[k] = v
266		}
267		return out
268	}
269	
270	// seriesKey builds a collision-free identity from name + unordered labels.
271	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
272	// so length-prefixed values remove any ambiguity from arbitrary label values.
273	func seriesKey(name string, labels map[string]string) string {
274		var b strings.Builder
275		b.WriteString(name)
276		for _, k := range sortedKeys(labels) {
277			b.WriteByte(0)
278			b.WriteString(k)
279			b.WriteByte(0)
280			v := labels[k]
281			b.WriteString(strconv.Itoa(len(v)))
282			b.WriteByte(0)
283			b.WriteString(v)
284		}
285		return b.String()
286	}
287	
288	func equalBuckets(a, b []float64) bool {
289		if len(a) != len(b) {
290			return false
291		}
292		for i := range a {
293			if a[i] != b[i] {
294				return false
295			}
296		}
297		return true
298	}
299	
300	// Handler returns the HTTP surface served by SignalWatch.
301	func Handler() http.Handler {
302		mux := http.NewServeMux()
303		store := newMetricStore()
304	
305		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
306			if r.Method != http.MethodGet {
307				w.Header().Set("Allow", http.MethodGet)
308				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
309				return
310			}
311			w.Header().Set("Content-Type", "application/json; charset=utf-8")
312			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
313		})
314	
315		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
316			switch r.Method {
317			case http.MethodGet:
318				handleMetricsGet(w, r, store)
319			case http.MethodPost:
320				handleMetricsPost(w, r, store)
321			default:
322				w.Header().Set("Allow", "GET, POST")
323				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
324			}
325		})
326	
327		registerAlertHandlers(mux, store)
328		registerSilenceHandlers(mux, store)
329		registerInhibitHandlers(mux, store)
330		registerNotificationRouteHandlers(mux, store)
331		registerSLOHandlers(mux, store)
332	
333		return mux
334	}
335	
336	func handleMetricsPost(w http.ResponseWriter, r *http.Request, store *metricStore) {
337		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
338		if err != nil || mediaType != "application/json" {
339			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
340			return
341		}
342	
343		body, err := io.ReadAll(r.Body)
344		if err != nil {
345			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
346			return
347		}
348	
349		batch, ok := decodeMetricsBatch(body)
350		if !ok {
351			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
352			return
353		}
354	
355		if !store.checkAndApply(batch) {
356			writeAPIError(w, "metric_conflict", http.StatusConflict)
357			return
358		}
359	
360		w.Header().Set("Content-Type", "application/json; charset=utf-8")
361		w.WriteHeader(http.StatusAccepted)
362		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
363	}
364	
365	type metricsEnvelope struct {
366		Samples *[]json.RawMessage `json:"samples"`
367	}
368	
369	type rawSample struct {
370		Name    *string            `json:"name"`
371		Type    *string            `json:"type"`
372		Labels  *map[string]string `json:"labels"`
373		Value   *float64           `json:"value"`
374		Buckets *[]float64         `json:"buckets"`
375	}
376	
377	// decodeMetricsBatch performs every format and value check. It never returns a
378	// partially validated batch.
379	func decodeMetricsBatch(body []byte) ([]validatedSample, bool) {
380		var env metricsEnvelope
381		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
382			return nil, false
383		}
384	
385		batch := make([]validatedSample, 0, len(*env.Samples))
386		for _, raw := range *env.Samples {
387			var sm rawSample
388			if !strictDecode(raw, &sm) {
389				return nil, false
390			}
391			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
392				return nil, false
393			}
394			name, typ := *sm.Name, *sm.Type
395			if !identPattern.MatchString(name) {
396				return nil, false
397			}
398			if typ != "counter" && typ != "gauge" && typ != "histogram" {
399				return nil, false
400			}
401			labels := *sm.Labels
402			if labels == nil {
403				return nil, false // explicit null labels
404			}
405			for k := range labels {
406				if !identPattern.MatchString(k) {
407					return nil, false
408				}
409			}
410			value := *sm.Value
411			if math.IsNaN(value) || math.IsInf(value, 0) {
412				return nil, false // encoding/json already rejects NaN/Inf tokens
413			}
414			if typ == "counter" && value < 0 {
415				return nil, false
416			}
417	
418			var buckets []float64
419			if typ == "histogram" {
420				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
421					return nil, false
422				}
423				buckets = append([]float64(nil), (*sm.Buckets)...)
424			} else if sm.Buckets != nil {
425				return nil, false // buckets only valid on histograms
426			}
427	
428			batch = append(batch, validatedSample{
429				key:     seriesKey(name, labels),
430				name:    name,
431				typ:     typ,
432				labels:  copyLabels(labels),
433				value:   value,
434				buckets: buckets,
435			})
436		}
437		return batch, true
438	}
439	
440	func validBuckets(buckets []float64) bool {
441		if len(buckets) == 0 {
442			return false
443		}
444		prev := math.Inf(-1)
445		for _, b := range buckets {
446			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
447				return false
448			}
449			prev = b
450		}
451		return true
452	}
453	
454	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
455	// values and non-object payloads for struct targets.
456	func strictDecode(data []byte, target any) bool {
457		dec := json.NewDecoder(bytes.NewReader(data))
458		dec.DisallowUnknownFields()
459		if err := dec.Decode(target); err != nil {
460			return false
461		}
462		var extra json.RawMessage
463		if err := dec.Decode(&extra); err != io.EOF {
464			return false
465		}
466		return true
467	}
468	
469	func handleMetricsGet(w http.ResponseWriter, r *http.Request, store *metricStore) {
470		values, err := url.ParseQuery(r.URL.RawQuery)
471		if err != nil {
472			writeAPIError(w, "invalid_query", http.StatusBadRequest)
473			return
474		}
475	
476		names := values["name"]
477		if len(names) == 0 || !identPattern.MatchString(names[0]) {
478			writeAPIError(w, "invalid_query", http.StatusBadRequest)
479			return
480		}
481	
482		selector := make(map[string]string)
483		for key, vals := range values {
484			if !strings.HasPrefix(key, "label.") {
485				continue
486			}
487			labelKey := strings.TrimPrefix(key, "label.")
488			if !identPattern.MatchString(labelKey) {
489				writeAPIError(w, "invalid_query", http.StatusBadRequest)
490				return
491			}
492			for _, v := range vals[1:] {
493				if v != vals[0] {
494					writeAPIError(w, "invalid_query", http.StatusBadRequest)
495					return
496				}
497			}
498			selector[labelKey] = vals[0]
499		}
500	
501		seriesList := store.query(names[0], selector)
502		w.Header().Set("Content-Type", "application/json; charset=utf-8")
503		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
504	}
505	
506	func writeAPIError(w http.ResponseWriter, code string, status int) {
507		w.Header().Set("Content-Type", "application/json; charset=utf-8")
508		w.WriteHeader(status)
509		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
510	}
511

